$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$migration = Decode ""
$api = Decode ""
$component = Decode ""
$componentImport = Decode "aW1wb3J0IEdyb3VwQ2FuY2VsbGF0aW9uQ2FyZCBmcm9tICIuL0dyb3VwQ2FuY2VsbGF0aW9uQ2FyZCI7Cg=="
$componentBlock = Decode ""

$migrationPath = Join-Path $root "supabase\migrations\20260812210700_klyx_group_cancellation_request_12_89.sql"
$apiPath = Join-Path $root "app\api\booking-groups\[id]\cancellation\route.ts"
$componentPath = Join-Path $root "app\booking-groups\[id]\GroupCancellationCard.tsx"
$pagePath = Join-Path $root "app\booking-groups\[id]\page.tsx"

if (-not (Test-Path -LiteralPath $pagePath)) {
    throw "12.89 : app\booking-groups\[id]\page.tsx introuvable."
}

$page = [System.IO.File]::ReadAllText($pagePath)

if (-not $page.Contains("KLYX_GROUP_MISSION_PAGE_12_87")) {
    throw "12.89 : marqueur 12.87 introuvable."
}

if (-not $page.Contains("KLYX_GROUP_REVIEW_CTA_12_88")) {
    throw "12.89 : marqueur 12.88 introuvable."
}

New-Item -ItemType Directory -Force -Path (Split-Path -Parent $migrationPath) | Out-Null
New-Item -ItemType Directory -Force -Path (Split-Path -Parent $apiPath) | Out-Null
New-Item -ItemType Directory -Force -Path (Split-Path -Parent $componentPath) | Out-Null

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

Copy-Item -LiteralPath $pagePath -Destination ($pagePath + ".bak-12-89-" + $timestamp) -Force

if (Test-Path -LiteralPath $apiPath) {
    Copy-Item -LiteralPath $apiPath -Destination ($apiPath + ".bak-12-89-" + $timestamp) -Force
}

if (Test-Path -LiteralPath $componentPath) {
    Copy-Item -LiteralPath $componentPath -Destination ($componentPath + ".bak-12-89-" + $timestamp) -Force
}

[System.IO.File]::WriteAllText($migrationPath, $migration, $utf8)
[System.IO.File]::WriteAllText($apiPath, $api, $utf8)
[System.IO.File]::WriteAllText($componentPath, $component, $utf8)

# ===========================================================
# IMPORT
# ===========================================================

if (-not $page.Contains('import GroupCancellationCard from "./GroupCancellationCard";')) {
    $marker = "// KLYX_GROUP_MISSION_PAGE_12_87"
    $markerIndex = $page.IndexOf($marker)

    if ($markerIndex -lt 0) {
        throw "12.89 : impossible d inserer l import."
    }

    $page = $page.Insert($markerIndex, $componentImport)
}

# ===========================================================
# COMPONENT
# ===========================================================

if (-not $page.Contains("KLYX_GROUP_CANCELLATION_CARD_12_89")) {
    $reviewMarker = "          {/* KLYX_GROUP_REVIEW_CTA_12_88 */}"
    $reviewIndex = $page.IndexOf($reviewMarker)

    if ($reviewIndex -lt 0) {
        throw "12.89 : point d insertion 12.88 introuvable."
    }

    $page = $page.Insert($reviewIndex, $componentBlock)
}

[System.IO.File]::WriteAllText($pagePath, $page, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 12.89 APPLIQUE"
Write-Host "======================================"
Write-Host "Demande annulation groupee : OK"
Write-Host "Motif obligatoire : OK"
Write-Host "Retrait demande : OK"
Write-Host "Audit serveur : OK"
Write-Host "Notification participant : OK"
Write-Host "Annulation automatique : NON"
Write-Host "Remboursement automatique : NON"
Write-Host "======================================"
Write-Host ""
